// generated by corpus.ts, inlined so the bundle runs without a filesystem
import { lexicon, prose } from './out/corpora.js';

/** A candidate is anything with the shipped engine's signature. */
export type Engine = (text: string, tag: string) => string;

/**
 * Four targets, cheapest to dearest, chosen so an optimisation cannot look
 * good by helping only the easy case:
 *
 *   isv-Latn              two passes; almost pure table lookup
 *   isv-Cyrl-x-iotated    eleven passes, several of them order-dependent
 *   isv-x-fonipa          eight passes, combining marks and tie bars
 *   isv-Latn-PL           forty-five passes; the pathological one
 */
export const TARGETS = [
  'isv-Latn',
  'isv-Cyrl-x-iotated',
  'isv-x-fonipa',
  'isv-Latn-PL',
] as const;

/** Every tag the engine answers to — used for the correctness gate, not timing. */
export const ALL_TAGS = [
  'isv-Latn', 'isv-Latn-x-etymolog', 'isv-Latn-x-northern', 'isv-Latn-x-southern',
  'isv-Latn-x-sloviant', 'isv-Latn-x-ascii', 'isv-Latn-PL',
  'isv-Cyrl', 'isv-Cyrl-x-etymolog', 'isv-Cyrl-x-northern', 'isv-Cyrl-x-southern',
  'isv-Cyrl-x-sloviant', 'isv-Cyrl-x-iotated', 'isv-Cyrl-x-iotated-ext',
  'isv-Glag', 'isv-Glag-x-etymolog', 'isv-Glag-x-northern', 'isv-Glag-x-southern',
  'isv-Glag-x-sloviant', 'isv-x-fonipa',
] as const;

export type Result = {
  name: string;
  correct: boolean;
  wrong: string[];
  /** words per second, per workload, per target */
  rates: Record<string, Record<string, number>>;
};

function bestOf(runs: number, fn: () => void): number {
  fn(); // warm up the JIT before the clock starts
  let best = Infinity;
  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    fn();
    best = Math.min(best, performance.now() - t0);
  }
  return best;
}

/**
 * A faster wrong answer is worth nothing, so correctness is checked first and
 * a candidate that fails is timed anyway but never ranked. The check is the
 * whole corpus through every tag, compared byte for byte with the baseline.
 */
export function run(
  baseline: Engine,
  candidates: { name: string; engine: Engine }[],
  runs = 2,
): Result[] {
  const workloads = { prose, lexicon };

  // Correctness wants variety, speed wants volume, and they are cheapest apart.
  // The gate runs a slice through all twenty tags — enough words to reach every
  // rule, few enough that forty passes cost seconds rather than minutes. The
  // whole-lexicon proof lives in `tools/dump`, not here.
  const sample = Object.fromEntries(
    Object.entries(workloads).map(([kind, text]) => [kind, text.slice(0, 24_000)]),
  );

  const expected: Record<string, string> = {};
  for (const [kind, text] of Object.entries(sample)) {
    for (const tag of ALL_TAGS) expected[`${kind}|${tag}`] = baseline(text, tag);
  }

  const wordCount = Object.fromEntries(
    Object.entries(workloads).map(([k, v]) => [k, v.split(/\s+/).length]),
  );

  return candidates.map(({ name, engine }) => {
    const wrong: string[] = [];
    for (const [kind, text] of Object.entries(sample)) {
      for (const tag of ALL_TAGS) {
        let got: string;
        try {
          got = engine(text, tag);
        } catch (error) {
          got = `THREW ${(error as Error).message}`;
        }
        if (got !== expected[`${kind}|${tag}`]) wrong.push(`${kind}/${tag}`);
      }
    }

    const rates: Record<string, Record<string, number>> = {};
    for (const [kind, text] of Object.entries(workloads)) {
      rates[kind] = {};
      for (const tag of TARGETS) {
        const ms = bestOf(runs, () => {
          engine(text, tag);
        });
        rates[kind][tag] = wordCount[kind] / (ms / 1000);
      }
    }

    return { name, correct: wrong.length === 0, wrong, rates };
  });
}
